import DTTPayloadRef
import DTTProvenance
try:
    from typing import Optional
except:
    pass

class DTTT(object):

    # DTTT
    def __init__(
        self,
        TILESET_ID = None,
        TILESET_NAME = None,
        TILING_SCHEME = 0,
        LEVEL = 0,
        X = 0,
        Y = 0,
        ROW_ORIGIN_NORTH = False,
        WEST_DEG = 0.0,
        SOUTH_DEG = 0.0,
        EAST_DEG = 0.0,
        NORTH_DEG = 0.0,
        MIN_HEIGHT_M = 0.0,
        MAX_HEIGHT_M = 0.0,
        PAYLOAD_FORMAT = 0,
        PAYLOAD_FORMAT_VERSION = None,
        PAYLOAD = None,
        GRID_WIDTH = 0,
        GRID_HEIGHT = 0,
        POST_SPACING_M = 0.0,
        SOURCE_POST_SPACING_M = 0.0,
        VERTICAL_DATUM = 0,
        VERTICAL_DATUM_NAME = None,
        HORIZONTAL_DATUM_NAME = None,
        VERTICAL_ACCURACY_M = 0.0,
        ACCURACY_CONFIDENCE = 0.0,
        HORIZONTAL_ACCURACY_M = 0.0,
        DATA_COVERAGE_FRACTION = 0.0,
        NO_DATA_VALUE = 0.0,
        WATER_MASK_KIND = 0,
        WATER_MASK = None,
        WATER_MASK_WIDTH = 0,
        WATER_MASK_HEIGHT = 0,
        WATER_MASK_PROVENANCE = None,
        VERTEX_NORMALS = None,
        LAND_COVER = None,
        CHILD_AVAILABILITY = 0,
        MAX_LEVEL = 0,
        SOURCE_CLASS = 0,
        PROVENANCE = None,
        EPOCH = None,
        ETAG = None,
        EXPIRES = None,
        REMARKS = None,
    ):
        self.TILESET_ID = TILESET_ID  # type: Optional[str]
        self.TILESET_NAME = TILESET_NAME  # type: Optional[str]
        self.TILING_SCHEME = TILING_SCHEME  # type: int
        self.LEVEL = LEVEL  # type: int
        self.X = X  # type: int
        self.Y = Y  # type: int
        self.ROW_ORIGIN_NORTH = ROW_ORIGIN_NORTH  # type: bool
        self.WEST_DEG = WEST_DEG  # type: float
        self.SOUTH_DEG = SOUTH_DEG  # type: float
        self.EAST_DEG = EAST_DEG  # type: float
        self.NORTH_DEG = NORTH_DEG  # type: float
        self.MIN_HEIGHT_M = MIN_HEIGHT_M  # type: float
        self.MAX_HEIGHT_M = MAX_HEIGHT_M  # type: float
        self.PAYLOAD_FORMAT = PAYLOAD_FORMAT  # type: int
        self.PAYLOAD_FORMAT_VERSION = PAYLOAD_FORMAT_VERSION  # type: Optional[str]
        self.PAYLOAD = PAYLOAD  # type: Optional[DTTPayloadRef.DTTPayloadRefT]
        self.GRID_WIDTH = GRID_WIDTH  # type: int
        self.GRID_HEIGHT = GRID_HEIGHT  # type: int
        self.POST_SPACING_M = POST_SPACING_M  # type: float
        self.SOURCE_POST_SPACING_M = SOURCE_POST_SPACING_M  # type: float
        self.VERTICAL_DATUM = VERTICAL_DATUM  # type: int
        self.VERTICAL_DATUM_NAME = VERTICAL_DATUM_NAME  # type: Optional[str]
        self.HORIZONTAL_DATUM_NAME = HORIZONTAL_DATUM_NAME  # type: Optional[str]
        self.VERTICAL_ACCURACY_M = VERTICAL_ACCURACY_M  # type: float
        self.ACCURACY_CONFIDENCE = ACCURACY_CONFIDENCE  # type: float
        self.HORIZONTAL_ACCURACY_M = HORIZONTAL_ACCURACY_M  # type: float
        self.DATA_COVERAGE_FRACTION = DATA_COVERAGE_FRACTION  # type: float
        self.NO_DATA_VALUE = NO_DATA_VALUE  # type: float
        self.WATER_MASK_KIND = WATER_MASK_KIND  # type: int
        self.WATER_MASK = WATER_MASK  # type: Optional[DTTPayloadRef.DTTPayloadRefT]
        self.WATER_MASK_WIDTH = WATER_MASK_WIDTH  # type: int
        self.WATER_MASK_HEIGHT = WATER_MASK_HEIGHT  # type: int
        self.WATER_MASK_PROVENANCE = WATER_MASK_PROVENANCE  # type: Optional[DTTProvenance.DTTProvenanceT]
        self.VERTEX_NORMALS = VERTEX_NORMALS  # type: Optional[DTTPayloadRef.DTTPayloadRefT]
        self.LAND_COVER = LAND_COVER  # type: Optional[DTTPayloadRef.DTTPayloadRefT]
        self.CHILD_AVAILABILITY = CHILD_AVAILABILITY  # type: int
        self.MAX_LEVEL = MAX_LEVEL  # type: int
        self.SOURCE_CLASS = SOURCE_CLASS  # type: int
        self.PROVENANCE = PROVENANCE  # type: Optional[DTTProvenance.DTTProvenanceT]
        self.EPOCH = EPOCH  # type: Optional[str]
        self.ETAG = ETAG  # type: Optional[str]
        self.EXPIRES = EXPIRES  # type: Optional[str]
        self.REMARKS = REMARKS  # type: Optional[str]

    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpDtt = DTT()
        tmpDtt.Init(buf, pos)
        return cls.InitFromObj(tmpDtt)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpDtt):
        x = DTTT()
        x._UnPack(tmpDtt)
        return x

    # DTTT
    def _UnPack(self, DTT):
        if DTT is None:
            return
        self.TILESET_ID = DTT.TILESET_ID()
        self.TILESET_NAME = DTT.TILESET_NAME()
        self.TILING_SCHEME = DTT.TILING_SCHEME()
        self.LEVEL = DTT.LEVEL()
        self.X = DTT.X()
        self.Y = DTT.Y()
        self.ROW_ORIGIN_NORTH = DTT.ROW_ORIGIN_NORTH()
        self.WEST_DEG = DTT.WEST_DEG()
        self.SOUTH_DEG = DTT.SOUTH_DEG()
        self.EAST_DEG = DTT.EAST_DEG()
        self.NORTH_DEG = DTT.NORTH_DEG()
        self.MIN_HEIGHT_M = DTT.MIN_HEIGHT_M()
        self.MAX_HEIGHT_M = DTT.MAX_HEIGHT_M()
        self.PAYLOAD_FORMAT = DTT.PAYLOAD_FORMAT()
        self.PAYLOAD_FORMAT_VERSION = DTT.PAYLOAD_FORMAT_VERSION()
        if DTT.PAYLOAD() is not None:
            self.PAYLOAD = DTTPayloadRef.DTTPayloadRefT.InitFromObj(DTT.PAYLOAD())
        self.GRID_WIDTH = DTT.GRID_WIDTH()
        self.GRID_HEIGHT = DTT.GRID_HEIGHT()
        self.POST_SPACING_M = DTT.POST_SPACING_M()
        self.SOURCE_POST_SPACING_M = DTT.SOURCE_POST_SPACING_M()
        self.VERTICAL_DATUM = DTT.VERTICAL_DATUM()
        self.VERTICAL_DATUM_NAME = DTT.VERTICAL_DATUM_NAME()
        self.HORIZONTAL_DATUM_NAME = DTT.HORIZONTAL_DATUM_NAME()
        self.VERTICAL_ACCURACY_M = DTT.VERTICAL_ACCURACY_M()
        self.ACCURACY_CONFIDENCE = DTT.ACCURACY_CONFIDENCE()
        self.HORIZONTAL_ACCURACY_M = DTT.HORIZONTAL_ACCURACY_M()
        self.DATA_COVERAGE_FRACTION = DTT.DATA_COVERAGE_FRACTION()
        self.NO_DATA_VALUE = DTT.NO_DATA_VALUE()
        self.WATER_MASK_KIND = DTT.WATER_MASK_KIND()
        if DTT.WATER_MASK() is not None:
            self.WATER_MASK = DTTPayloadRef.DTTPayloadRefT.InitFromObj(DTT.WATER_MASK())
        self.WATER_MASK_WIDTH = DTT.WATER_MASK_WIDTH()
        self.WATER_MASK_HEIGHT = DTT.WATER_MASK_HEIGHT()
        if DTT.WATER_MASK_PROVENANCE() is not None:
            self.WATER_MASK_PROVENANCE = DTTProvenance.DTTProvenanceT.InitFromObj(DTT.WATER_MASK_PROVENANCE())
        if DTT.VERTEX_NORMALS() is not None:
            self.VERTEX_NORMALS = DTTPayloadRef.DTTPayloadRefT.InitFromObj(DTT.VERTEX_NORMALS())
        if DTT.LAND_COVER() is not None:
            self.LAND_COVER = DTTPayloadRef.DTTPayloadRefT.InitFromObj(DTT.LAND_COVER())
        self.CHILD_AVAILABILITY = DTT.CHILD_AVAILABILITY()
        self.MAX_LEVEL = DTT.MAX_LEVEL()
        self.SOURCE_CLASS = DTT.SOURCE_CLASS()
        if DTT.PROVENANCE() is not None:
            self.PROVENANCE = DTTProvenance.DTTProvenanceT.InitFromObj(DTT.PROVENANCE())
        self.EPOCH = DTT.EPOCH()
        self.ETAG = DTT.ETAG()
        self.EXPIRES = DTT.EXPIRES()
        self.REMARKS = DTT.REMARKS()

    # DTTT
    def Pack(self, builder):
        if self.TILESET_ID is not None:
            TILESET_ID = builder.CreateString(self.TILESET_ID)
        if self.TILESET_NAME is not None:
            TILESET_NAME = builder.CreateString(self.TILESET_NAME)
        if self.PAYLOAD_FORMAT_VERSION is not None:
            PAYLOAD_FORMAT_VERSION = builder.CreateString(self.PAYLOAD_FORMAT_VERSION)
        if self.PAYLOAD is not None:
            PAYLOAD = self.PAYLOAD.Pack(builder)
        if self.VERTICAL_DATUM_NAME is not None:
            VERTICAL_DATUM_NAME = builder.CreateString(self.VERTICAL_DATUM_NAME)
        if self.HORIZONTAL_DATUM_NAME is not None:
            HORIZONTAL_DATUM_NAME = builder.CreateString(self.HORIZONTAL_DATUM_NAME)
        if self.WATER_MASK is not None:
            WATER_MASK = self.WATER_MASK.Pack(builder)
        if self.WATER_MASK_PROVENANCE is not None:
            WATER_MASK_PROVENANCE = self.WATER_MASK_PROVENANCE.Pack(builder)
        if self.VERTEX_NORMALS is not None:
            VERTEX_NORMALS = self.VERTEX_NORMALS.Pack(builder)
        if self.LAND_COVER is not None:
            LAND_COVER = self.LAND_COVER.Pack(builder)
        if self.PROVENANCE is not None:
            PROVENANCE = self.PROVENANCE.Pack(builder)
        if self.EPOCH is not None:
            EPOCH = builder.CreateString(self.EPOCH)
        if self.ETAG is not None:
            ETAG = builder.CreateString(self.ETAG)
        if self.EXPIRES is not None:
            EXPIRES = builder.CreateString(self.EXPIRES)
        if self.REMARKS is not None:
            REMARKS = builder.CreateString(self.REMARKS)
        DTTStart(builder)
        if self.TILESET_ID is not None:
            DTTAddTILESET_ID(builder, TILESET_ID)
        if self.TILESET_NAME is not None:
            DTTAddTILESET_NAME(builder, TILESET_NAME)
        DTTAddTILING_SCHEME(builder, self.TILING_SCHEME)
        DTTAddLEVEL(builder, self.LEVEL)
        DTTAddX(builder, self.X)
        DTTAddY(builder, self.Y)
        DTTAddROW_ORIGIN_NORTH(builder, self.ROW_ORIGIN_NORTH)
        DTTAddWEST_DEG(builder, self.WEST_DEG)
        DTTAddSOUTH_DEG(builder, self.SOUTH_DEG)
        DTTAddEAST_DEG(builder, self.EAST_DEG)
        DTTAddNORTH_DEG(builder, self.NORTH_DEG)
        DTTAddMIN_HEIGHT_M(builder, self.MIN_HEIGHT_M)
        DTTAddMAX_HEIGHT_M(builder, self.MAX_HEIGHT_M)
        DTTAddPAYLOAD_FORMAT(builder, self.PAYLOAD_FORMAT)
        if self.PAYLOAD_FORMAT_VERSION is not None:
            DTTAddPAYLOAD_FORMAT_VERSION(builder, PAYLOAD_FORMAT_VERSION)
        if self.PAYLOAD is not None:
            DTTAddPAYLOAD(builder, PAYLOAD)
        DTTAddGRID_WIDTH(builder, self.GRID_WIDTH)
        DTTAddGRID_HEIGHT(builder, self.GRID_HEIGHT)
        DTTAddPOST_SPACING_M(builder, self.POST_SPACING_M)
        DTTAddSOURCE_POST_SPACING_M(builder, self.SOURCE_POST_SPACING_M)
        DTTAddVERTICAL_DATUM(builder, self.VERTICAL_DATUM)
        if self.VERTICAL_DATUM_NAME is not None:
            DTTAddVERTICAL_DATUM_NAME(builder, VERTICAL_DATUM_NAME)
        if self.HORIZONTAL_DATUM_NAME is not None:
            DTTAddHORIZONTAL_DATUM_NAME(builder, HORIZONTAL_DATUM_NAME)
        DTTAddVERTICAL_ACCURACY_M(builder, self.VERTICAL_ACCURACY_M)
        DTTAddACCURACY_CONFIDENCE(builder, self.ACCURACY_CONFIDENCE)
        DTTAddHORIZONTAL_ACCURACY_M(builder, self.HORIZONTAL_ACCURACY_M)
        DTTAddDATA_COVERAGE_FRACTION(builder, self.DATA_COVERAGE_FRACTION)
        DTTAddNO_DATA_VALUE(builder, self.NO_DATA_VALUE)
        DTTAddWATER_MASK_KIND(builder, self.WATER_MASK_KIND)
        if self.WATER_MASK is not None:
            DTTAddWATER_MASK(builder, WATER_MASK)
        DTTAddWATER_MASK_WIDTH(builder, self.WATER_MASK_WIDTH)
        DTTAddWATER_MASK_HEIGHT(builder, self.WATER_MASK_HEIGHT)
        if self.WATER_MASK_PROVENANCE is not None:
            DTTAddWATER_MASK_PROVENANCE(builder, WATER_MASK_PROVENANCE)
        if self.VERTEX_NORMALS is not None:
            DTTAddVERTEX_NORMALS(builder, VERTEX_NORMALS)
        if self.LAND_COVER is not None:
            DTTAddLAND_COVER(builder, LAND_COVER)
        DTTAddCHILD_AVAILABILITY(builder, self.CHILD_AVAILABILITY)
        DTTAddMAX_LEVEL(builder, self.MAX_LEVEL)
        DTTAddSOURCE_CLASS(builder, self.SOURCE_CLASS)
        if self.PROVENANCE is not None:
            DTTAddPROVENANCE(builder, PROVENANCE)
        if self.EPOCH is not None:
            DTTAddEPOCH(builder, EPOCH)
        if self.ETAG is not None:
            DTTAddETAG(builder, ETAG)
        if self.EXPIRES is not None:
            DTTAddEXPIRES(builder, EXPIRES)
        if self.REMARKS is not None:
            DTTAddREMARKS(builder, REMARKS)
        DTT = DTTEnd(builder)
        return DTT
